package com.prashant.KhetWallah.message;

import com.prashant.KhetWallah.admin.*;
import com.prashant.KhetWallah.order.*;
import com.prashant.KhetWallah.listing.*;
import com.prashant.KhetWallah.user.*;
import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;
import org.springframework.data.domain.*;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.web.server.ResponseStatusException;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

class OrderMessageServiceTest {
 final OrderMessageRepository messages=mock(OrderMessageRepository.class); final MessageReportRepository reports=mock(MessageReportRepository.class); final OrderRepository orders=mock(OrderRepository.class); final AppUserRepository users=mock(AppUserRepository.class); final AdminActionRepository actions=mock(AdminActionRepository.class);
 final Instant now=Instant.parse("2026-10-20T10:00:00Z");final OrderMessageService service=new OrderMessageService(messages,reports,orders,users,actions,Clock.fixed(now,ZoneOffset.UTC));
 final AppUser buyer=mock(AppUser.class),farmer=mock(AppUser.class),outsider=mock(AppUser.class),admin=mock(AppUser.class); final OrderEntity order=mock(OrderEntity.class);final ListingEntity listing=mock(ListingEntity.class);
 @BeforeEach void setup(){account(buyer,2L,"Buyer","buyer@test.example");account(farmer,1L,"Farmer","farmer@test.example");account(outsider,3L,"Other","outsider@test.example");account(admin,4L,"Admin","admin@test.example");when(admin.getRole()).thenReturn(UserRole.ADMIN);when(order.getId()).thenReturn(10L);when(order.getBuyer()).thenReturn(buyer);when(order.getListing()).thenReturn(listing);when(listing.getOwner()).thenReturn(farmer);when(listing.getProduceName()).thenReturn("Tomato");when(orders.findById(10L)).thenReturn(Optional.of(order));when(messages.saveAndFlush(any())).thenAnswer(c->{OrderMessage message=c.getArgument(0);ReflectionTestUtils.setField(message,"id",20L);return message;});when(messages.findByOrder_IdOrderByIdDesc(eq(10L),any())).thenReturn(new PageImpl<>(List.of()));}
 void account(AppUser user,Long id,String name,String email){when(user.getId()).thenReturn(id);when(user.getDisplayName()).thenReturn(name);when(user.getEmail()).thenReturn(email);when(users.findByEmail(email)).thenReturn(Optional.of(user));when(users.findByIdForUpdate(id)).thenReturn(Optional.of(user));}
 OrderMessage message(){OrderMessage message=new OrderMessage(order,buyer,farmer,"Hello",now);ReflectionTestUtils.setField(message,"id",20L);when(messages.findById(20L)).thenReturn(Optional.of(message));when(messages.findByIdForUpdate(20L)).thenReturn(Optional.of(message));return message;}
 @Test void buyerAndFarmerCanSendAndRecipientIsDerivedFromOrder(){var fromBuyer=service.send(10L," Hello farmer ",buyer.getEmail());assertEquals("Hello farmer",fromBuyer.body());assertTrue(fromBuyer.mine());var fromFarmer=service.send(10L,"Hello buyer",farmer.getEmail());assertEquals("Farmer",fromFarmer.senderName());var cap=ArgumentCaptor.forClass(OrderMessage.class);verify(messages,times(2)).saveAndFlush(cap.capture());assertSame(farmer,cap.getAllValues().getFirst().getRecipient());assertSame(buyer,cap.getAllValues().getLast().getRecipient());}
 @Test void bothParticipantsCanReadTheSameOrder(){service.list(10L,buyer.getEmail(),0,20);service.list(10L,farmer.getEmail(),0,20);verify(messages,times(2)).findByOrder_IdOrderByIdDesc(eq(10L),any());}
 @Test void outsidersCannotReadOrSendAndCannotChooseRecipient(){assertStatus(404,()->service.list(10L,outsider.getEmail(),0,20));assertStatus(404,()->service.send(10L,"Leak",outsider.getEmail()));verify(messages,never()).saveAndFlush(any());verify(messages,never()).findByOrder_IdOrderByIdDesc(any(),any());}
 @Test void missingOrderAndUnknownUserAreRejected(){assertStatus(404,()->service.list(999L,buyer.getEmail(),0,20));assertStatus(401,()->service.list(10L,"missing@example.test",0,20));}
 @Test void suspendedAccountsCannotReadOrSend(){when(buyer.isSuspended()).thenReturn(true);assertStatus(401,()->service.list(10L,buyer.getEmail(),0,20));assertStatus(401,()->service.send(10L,"Hello",buyer.getEmail()));}
 @Test void blankAndLongBodiesFailBeforePersisting(){for(String body:Arrays.asList(null," ","x".repeat(2001)))assertStatus(400,()->service.send(10L,body,buyer.getEmail()));verify(messages,never()).saveAndFlush(any());}
 @Test void userLockAndPersistedCountsGuardMinuteBudgetAcrossOrders(){when(messages.recentSentForUpdate(eq(2L),eq(now.minusSeconds(3600)),any())).thenReturn(Collections.nCopies(10,new OrderMessage(order,buyer,farmer,"Hello",now)));assertStatus(429,()->service.send(10L,"Limit",buyer.getEmail()));verify(users).findByIdForUpdate(2L);verify(messages,never()).saveAndFlush(any());}
 @Test void persistedHourBudgetSurvivesMinuteWindow(){when(messages.recentSentForUpdate(eq(2L),eq(now.minusSeconds(3600)),any())).thenReturn(Collections.nCopies(120,new OrderMessage(order,buyer,farmer,"Old message",now.minusSeconds(120))));assertStatus(429,()->service.send(10L,"Limit",buyer.getEmail()));verify(messages).recentSentForUpdate(eq(2L),eq(now.minusSeconds(3600)),any());verify(messages,never()).saveAndFlush(any());}
 @Test void readOnlyUpdatesRecipientAndRequestedOrder(){message();service.markRead(10L,20L,farmer.getEmail());verify(messages).markRead(10L,1L,20L,now);verify(messages,never()).markRead(eq(10L),eq(2L),anyLong(),any());}
 @Test void outsiderReadAndForeignMessageReadReturn404(){message();assertStatus(404,()->service.markRead(10L,20L,outsider.getEmail()));OrderEntity another=mock(OrderEntity.class);when(another.getId()).thenReturn(99L);OrderMessage other=new OrderMessage(another,buyer,farmer,"Other",now);when(messages.findById(21L)).thenReturn(Optional.of(other));assertStatus(404,()->service.markRead(10L,21L,buyer.getEmail()));verify(messages,never()).markRead(any(),any(),any(),any());}
 @Test void unreadCountsAreAlwaysCurrentAccountScoped(){when(messages.countByRecipient_IdAndReadAtIsNull(2L)).thenReturn(7L);assertEquals(7,service.unread(buyer.getEmail()));verify(messages).countByRecipient_IdAndReadAtIsNull(2L);}
 @Test void hiddenBodyIsRedactedForBothParticipants(){OrderMessage message=message();message.setHidden(true);when(messages.findByOrder_IdOrderByIdDesc(eq(10L),any())).thenReturn(new PageImpl<>(List.of(message)));assertNull(service.list(10L,buyer.getEmail(),0,20).content().getFirst().body());assertNull(service.list(10L,farmer.getEmail(),0,20).content().getFirst().body());}
 @Test void reportsRequireRecipientOwnershipAndReason(){message();service.report(20L," Misleading request ",farmer.getEmail());var cap=ArgumentCaptor.forClass(MessageReport.class);verify(reports).save(cap.capture());assertEquals("Misleading request",cap.getValue().getReason());assertStatus(404,()->service.report(20L,"Reason",outsider.getEmail()));assertStatus(400,()->service.report(20L,"Reason",buyer.getEmail()));assertStatus(400,()->service.report(20L," ",farmer.getEmail()));}
 @Test void duplicateReportIsIdempotentAndReportSpamIsLimited(){message();when(reports.existingForUpdate(20L,1L)).thenReturn(Optional.of(new MessageReport(new OrderMessage(order,buyer,farmer,"Hello",now),farmer,"Reason",now)));service.report(20L,"Reason",farmer.getEmail());verify(reports,never()).save(any());when(reports.existingForUpdate(20L,1L)).thenReturn(Optional.empty());when(reports.recentReportsForUpdate(eq(1L),eq(now.minusSeconds(3600)),any())).thenReturn(Collections.nCopies(20,new MessageReport(new OrderMessage(order,buyer,farmer,"Hello",now),farmer,"Reason",now)));assertStatus(429,()->service.report(20L,"Reason",farmer.getEmail()));}
 @Test void moderationRequiresAdminAndRecordsReasonAndTarget(){OrderMessage message=message();assertStatus(403,()->service.moderate(20L,true,"Bad content",buyer.getEmail()));service.moderate(20L,true," Bad content ",admin.getEmail());assertTrue(message.isHidden());service.moderate(20L,false,"Appeal accepted",admin.getEmail());assertFalse(message.isHidden());var cap=ArgumentCaptor.forClass(AdminAction.class);verify(actions,times(2)).save(cap.capture());assertEquals("HIDE_MESSAGE",cap.getAllValues().getFirst().getAction());assertEquals("Bad content",cap.getAllValues().getFirst().getReason());assertEquals("RESTORE_MESSAGE",cap.getValue().getAction());assertEquals(20L,cap.getValue().getTargetId());}
 @Test void moderationNoOpAndMissingReasonFail(){message();assertStatus(400,()->service.moderate(20L,true," ",admin.getEmail()));assertStatus(409,()->service.moderate(20L,false,"No-op",admin.getEmail()));verify(actions,never()).save(any());}
 @Test void reportedContentOnlyAdminCanRead(){OrderMessage message=message();MessageReport report=new MessageReport(message,farmer,"Reason",now);when(reports.findAllByOrderByIdDesc(any())).thenReturn(new PageImpl<>(List.of(report)));assertStatus(403,()->service.reported(buyer.getEmail(),0,20));assertEquals("Hello",service.reported(admin.getEmail(),0,20).getContent().getFirst().body());}
 @Test void conversationLinksAndUnreadCountAreDerivedForSignedInRole(){OrderMessage message=message();when(messages.conversations(eq(2L),any())).thenReturn(new PageImpl<>(List.of(message)));when(messages.conversations(eq(1L),any())).thenReturn(new PageImpl<>(List.of(message)));when(messages.countByOrder_IdAndRecipient_IdAndReadAtIsNull(10L,2L)).thenReturn(3L);var buyerView=service.conversations(buyer.getEmail(),0,20).getContent().getFirst();assertEquals("/my-orders.html?orderId=10#order-10",buyerView.targetUrl());assertEquals(3,buyerView.unreadCount());assertEquals("Farmer",buyerView.otherName());assertEquals("/received-orders.html?orderId=10#order-10",service.conversations(farmer.getEmail(),0,20).getContent().getFirst().targetUrl());}
 @Test void paginationCannotBeUnbounded(){assertStatus(400,()->service.list(10L,buyer.getEmail(),-1,20));assertStatus(400,()->service.list(10L,buyer.getEmail(),0,51));assertStatus(400,()->service.conversations(buyer.getEmail(),0,0));}
 @Test void publicViewContainsNoEmailsOrRecipientIds(){assertEquals(Set.of("id","orderId","senderName","mine","body","hidden","createdAt","readAt"),new HashSet<>(Arrays.stream(OrderMessageService.MessageView.class.getRecordComponents()).map(java.lang.reflect.RecordComponent::getName).toList()));assertFalse(message().toString().contains("Hello"));}
 private static void assertStatus(int status,Runnable action){assertEquals(status,assertThrows(ResponseStatusException.class,action::run).getStatusCode().value());}
}
